<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require __DIR__.'/../global/connection.php';require_once __DIR__.'/../modules/inventory/stock.php';require_once __DIR__.'/qa-http-client.php';
if(!str_ends_with(DB,'_qa'))throw new RuntimeException('Use una base _qa.');
$http=new AppQaHttpClient(getenv('APPU_QA_URL')?:'http://127.0.0.1:8765',DB);$key='QA-TR-'.bin2hex(random_bytes(4));$product=$warehouse2=$transfer=null;$failed=false;
function transferAssert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
try{
 $user=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn();$warehouse1=(int)$pdo->query('SELECT id FROM tbl_warehouse WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();
 $pdo->prepare("INSERT INTO tbl_warehouse(code,name,address,active_status) VALUES(?,?,'QA',1)")->execute([$key,'Almacén destino QA']);$warehouse2=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO tbl_product(code,brand,name,description,stock_quantity,unit_price,unit_value,active_status) VALUES(?,'QA','Artículo traslado QA','Temporal',0,10,'UND',1)")->execute([$key]);$product=(int)$pdo->lastInsertId();
 $pdo->beginTransaction();warehouse_apply_stock_delta($pdo,$product,10,STOCK_MOVEMENT_ENTRY,$user,'Saldo inicial transferencia','inventory_document',990001,$key,null,$warehouse1,100);warehouse_apply_lot_delta($pdo,$product,$warehouse1,$key.'-LOT',date('Y-m-d',strtotime('+180 days')),10);$pdo->commit();$lot=(int)$pdo->query("SELECT id FROM tbl_product_lot WHERE product_id={$product} AND warehouse_id={$warehouse1}")->fetchColumn();
 [$status,$catalog]=$http->request('/modules/inventory/transfers.php');transferAssert($status===200,'No cargó el formulario de transferencias.');transferAssert(count(array_filter($catalog['warehouses'],fn($w)=>(int)$w['id']===$warehouse2))===1,'El almacén destino no aparece en el selector.');
 foreach([['quantity'=>0.0001],['quantity'=>1.0001],['action'=>'desconocida']] as $invalid){[$status]=$http->request('/modules/inventory/transfers.php',array_merge(['product_id'=>$product,'from_warehouse_id'=>$warehouse1,'to_warehouse_id'=>$warehouse2,'quantity'=>1,'lot_id'=>$lot],$invalid));transferAssert($status===422,'Se aceptó una transferencia con acción/precisión inválida.');}
 $pdo->prepare('UPDATE tbl_product SET active_status=0 WHERE id=?')->execute([$product]);[$status]=$http->request('/modules/inventory/transfers.php',['product_id'=>$product,'from_warehouse_id'=>$warehouse1,'to_warehouse_id'=>$warehouse2,'quantity'=>1,'lot_id'=>$lot]);transferAssert($status===422,'Se permitió trasladar un artículo inactivo.');$pdo->prepare('UPDATE tbl_product SET active_status=1 WHERE id=?')->execute([$product]);
 [$status,$created]=$http->request('/modules/inventory/transfers.php',['product_id'=>$product,'from_warehouse_id'=>$warehouse1,'to_warehouse_id'=>$warehouse2,'quantity'=>4,'lot_id'=>$lot]);transferAssert($status===200,'No se registró la transferencia: '.json_encode($created));$q=$pdo->prepare('SELECT id FROM tbl_inventory_transfer WHERE number=?');$q->execute([$created['reference']]);$transfer=(int)$q->fetchColumn();transferAssert($transfer>0,'No se persistió la cabecera.');
 $history=$pdo->prepare("SELECT COUNT(*) FROM tbl_document_status_history WHERE document_type='stock_transfer' AND document_id=? AND new_status='Registrada'");$history->execute([$transfer]);transferAssert((int)$history->fetchColumn()===1,'La transferencia no registró su estado inicial.');
 $stock=$pdo->prepare('SELECT quantity,reserved_quantity,inventory_value,average_unit_cost FROM tbl_warehouse_stock WHERE warehouse_id=? AND product_id=?');$stock->execute([$warehouse1,$product]);$from=array_map('floatval',$stock->fetch());$stock->execute([$warehouse2,$product]);$to=array_map('floatval',$stock->fetch());transferAssert($from===['quantity'=>6.0,'reserved_quantity'=>0.0,'inventory_value'=>60.0,'average_unit_cost'=>10.0],'El almacén origen no conserva cantidad y valoración.');transferAssert($to===['quantity'=>4.0,'reserved_quantity'=>0.0,'inventory_value'=>40.0,'average_unit_cost'=>10.0],'El almacén destino no recibió cantidad y valoración.');
 $ledger=$pdo->prepare("SELECT SUM(quantity) quantity,SUM(inventory_value_delta) value_delta FROM tbl_warehouse_movement WHERE source_type='warehouse_transfer' AND source_id=?");$ledger->execute([$transfer]);$movement=$ledger->fetch();transferAssert(abs((float)$movement['quantity'])<.001&&abs((float)$movement['value_delta'])<.01,'El ledger del traslado no balancea cantidad y valor.');
 [$status,$error]=$http->request('/modules/inventory/transfers.php',['product_id'=>$product,'from_warehouse_id'=>$warehouse1,'to_warehouse_id'=>$warehouse2,'quantity'=>7,'lot_id'=>$lot]);transferAssert($status===422,'Se permitió transferir más que el saldo disponible.');
 [$status,$cancelled]=$http->request('/modules/inventory/transfers.php',['action'=>'cancel','transfer_id'=>$transfer,'cancellation_reason'=>'Reversión integral QA']);transferAssert($status===200,'No se anuló la transferencia: '.json_encode($cancelled));$stock->execute([$warehouse1,$product]);$from=array_map('floatval',$stock->fetch());$stock->execute([$warehouse2,$product]);$to=array_map('floatval',$stock->fetch());transferAssert($from===['quantity'=>10.0,'reserved_quantity'=>0.0,'inventory_value'=>100.0,'average_unit_cost'=>10.0],'La reversión no restauró origen y valor.');transferAssert($to===['quantity'=>0.0,'reserved_quantity'=>0.0,'inventory_value'=>0.0,'average_unit_cost'=>0.0],'La reversión no vació destino y valor.');
 $lotQty=$pdo->prepare('SELECT warehouse_id,quantity FROM tbl_product_lot WHERE product_id=? ORDER BY warehouse_id');$lotQty->execute([$product]);$lots=[];foreach($lotQty->fetchAll() as $row)$lots[(int)$row['warehouse_id']]=(float)$row['quantity'];transferAssert(($lots[$warehouse1]??-1)===10.0&&($lots[$warehouse2]??-1)===0.0,'La reversión no restauró los lotes.');echo "PASS HTTP warehouse transfer quantity value lot ledger overdraw rejection and cancellation\n";
}catch(Throwable $e){fwrite(STDERR,'FAIL inventory transfer HTTP: '.$e->getMessage().PHP_EOL);$failed=true;}
finally{
 if($pdo->inTransaction())$pdo->rollBack();$pdo->beginTransaction();if($transfer){$pdo->prepare("DELETE FROM tbl_document_status_history WHERE document_type='stock_transfer' AND document_id=?")->execute([$transfer]);$pdo->prepare("DELETE FROM tbl_custom_field_value WHERE entity='stock_transfer' AND record_id=?")->execute([$transfer]);$pdo->prepare("DELETE FROM tbl_warehouse_movement WHERE source_type='warehouse_transfer' AND source_id=?")->execute([$transfer]);$pdo->prepare('DELETE FROM tbl_inventory_transfer WHERE id=?')->execute([$transfer]);}if($product){$pdo->prepare('DELETE FROM tbl_warehouse_movement WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_product_lot WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_warehouse_stock WHERE product_id=?')->execute([$product]);$pdo->prepare('DELETE FROM tbl_product WHERE id=?')->execute([$product]);}if($warehouse2)$pdo->prepare('DELETE FROM tbl_warehouse WHERE id=?')->execute([$warehouse2]);$pdo->commit();
}
exit($failed?1:0);
